from __future__ import annotations
import argparse,csv,json,sqlite3,subprocess,sys,zipfile
from pathlib import Path
NS='''xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:table="urn:oasis:names:tc:opendocument:xmlns:table:1.0" xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0"'''
DATA=[('SUB-001','subscription','2026-Q4','INV-81',120,'USD','POSTED'),('SUB-002','subscription','2026-Q4','INV-82',80,'USD','POSTED'),('SUB-003','subscription','2026-Q4','INV-83',-20,'USD','CREDIT'),('SUB-X','subscription','2026-Q3','INV-70',999,'USD','VOID'),('FUL-101','fulfillment','2026-Q4','SHIP-41',4,'unit','DELIVERED'),('FUL-102','fulfillment','2026-Q4','SHIP-42',2,'unit','PARTIAL'),('FUL-103','fulfillment','2026-Q4','SHIP-43',1,'unit','VOID_LABEL'),('FUL-104','fulfillment','2026-Q4','SHIP-44',-1,'unit','RETURN_CREDIT')]
def ods(path):
 def c(v):return f'<table:table-cell office:value-type="string"><text:p>{v}</text:p></table:table-cell>'
 sheets=''
 for name,headers in [('Readme',['Quarter closeout']),('Subscriptions',['line_id','decision','amount','reason']),('Fulfillment',['line_id','decision','amount','reason']),('Adjustments',['adjustment_id','line_id','amount']),('Close Summary',['business_line','accepted','adjusted','disputed'])]:sheets+=f'<table:table table:name="{name}"><table:table-row>'+''.join(c(h) for h in headers)+'</table:table-row></table:table>'
 content=f'<?xml version="1.0"?><office:document-content {NS} office:version="1.2"><office:body><office:spreadsheet>{sheets}</office:spreadsheet></office:body></office:document-content>'
 with zipfile.ZipFile(path,'w') as z:z.writestr('mimetype','application/vnd.oasis.opendocument.spreadsheet',compress_type=zipfile.ZIP_STORED);z.writestr('content.xml',content);z.writestr('META-INF/manifest.xml','<manifest:manifest xmlns:manifest="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0"/>')
def main():
 p=argparse.ArgumentParser();p.add_argument('--workspace',required=True);p.add_argument('--source-dir',required=True);p.add_argument('--start-service',action='store_true');p.add_argument('--open-apps',action='store_true');a=p.parse_args();r=Path(a.workspace).expanduser().resolve()/'closeout';(r/'data').mkdir(parents=True,exist_ok=True);(r/'private/actor_a').mkdir(parents=True,exist_ok=True);(r/'private/actor_b').mkdir(parents=True,exist_ok=True);(r/'out').mkdir(exist_ok=True)
 for role,rows,policy in [('actor_a',[x for x in DATA if x[1]=='subscription'],'Match posted charges by invoice; include posted credits; exclude void and other-period rows. Credit amounts reduce the settlement total.'),('actor_b',[x for x in DATA if x[1]=='fulfillment'],'Count delivered quantities; partial shipments count only received units; void labels are excluded; return credits reduce the final unit balance.')]:
  with (r/f'private/{role}/statement.csv').open('w',encoding='utf-8',newline='') as f:w=csv.writer(f);w.writerow(['line_id','business_line','period','reference','amount','unit','status']);w.writerows(rows)
  (r/f'private/{role}/policy.txt').write_text(policy+' Decision schema: line_id, decision, amount, reason. POSTED/DELIVERED = matched; CREDIT/PARTIAL/RETURN_CREDIT = adjusted using signed amount or received units; VOID_LABEL = disputed with zero amount. Exclude prior-period and VOID subscriptions. Reports use decisions array and totals object.\n',encoding='utf-8')
 db=sqlite3.connect(r/'data/closeout.db');db.executescript('CREATE TABLE statement_line(line_id TEXT PRIMARY KEY,business_line TEXT,period TEXT,ref TEXT,amount REAL,unit TEXT,status TEXT); CREATE TABLE reconciliation(line_id TEXT PRIMARY KEY,decision TEXT,amount REAL,reason TEXT,revision INTEGER); CREATE TABLE dashboard_revision(revision INTEGER); INSERT INTO dashboard_revision VALUES(0); CREATE TABLE audit_event(revision INTEGER,scope TEXT,operation TEXT,row_count INTEGER);')
 db.executemany('INSERT INTO statement_line VALUES(?,?,?,?,?,?,?)',DATA);db.commit();db.close();ods(r/'quarter_closeout.ods');(r/'closeout_rules.txt').write_text('Use current quarter Q4 only. Record each in-scope line exactly once as matched, adjusted, or disputed. Every decision must have a source-based reason. Use Preview to review missing/invalid rows before Commit. Export one JSON and PDF per business line.\n',encoding='utf-8')
 if a.start_service:
  log=(r/'service.log').open('ab',buffering=0);subprocess.Popen([sys.executable,str(Path(a.source_dir)/'closeout_service.py'),'--root',str(r)],stdout=log,stderr=log,start_new_session=True);log.close()
 if a.open_apps:subprocess.Popen(['libreoffice','--calc',str(r/'quarter_closeout.ods')],start_new_session=True);subprocess.Popen(['google-chrome','http://127.0.0.1:18224/closeout'],start_new_session=True)
if __name__=='__main__':main()
